// Generado por tools/vu1/generar_vu1.cpp a partir del microcódigo del juego. No publicar.
#include "runtime/ps2_vu1.h"
#include "ps2_vu1_compiled.inl"
#include <cstdio>
#include <cstdlib>
#include <cstring>

// Mismo modo de coma flotante que el intérprete de VU (MSVC no expande en línea entre modos distintos).
#if defined(_MSC_VER)
#pragma float_control(precise, on, push)
#pragma fp_contract(off)
#endif

using P = VU1CompiledAccess::P;
using C = VU1CompiledAccess::C;

namespace
{
    // GOW_VU1C_DIAG: pares compilados e interpretados al salir. GOW_VU1C_RANGO=inicio-fin (hex): solo usa el
    // código compilado en ese rango de direcciones (para acotar una diferencia con el intérprete).
    // GOW_VU1C_SIN_BLOQUES: sin bloques (solo pares sueltos).
    struct Stats
    {
        struct Counter
        {
            unsigned long long val = 0;
            bool isCompiled = false;
            Counter(bool compiled) : isCompiled(compiled) {}
            Counter &operator++()
            {
                ++val;
                static unsigned long long total = 0;
                static unsigned long long comp = 0;
                static unsigned long long interp = 0;
                if (isCompiled) ++comp; else ++interp;
                if ((++total & 0x1FFFFFull) == 0)
                {
                    if (std::getenv("GOW_VU1C_DIAG"))
                        std::fprintf(stderr, "[vu1c-live] total=%llu comp=%llu interp=%llu (%.1f%% comp)\n",
                                     total, comp, interp, (comp * 100.0) / (total + 1));
                }
                return *this;
            }
            operator unsigned long long() const { return val; }
        };
        Counter compiled{true};
        Counter interpreted{false};
        ~Stats()
        {
            if (std::getenv("GOW_VU1C_DIAG"))
                std::fprintf(stderr, "[vu1c] compilados=%llu interpretados=%llu\n", (unsigned long long)compiled, (unsigned long long)interpreted);
        }
    } g_stats;
    struct Range
    {
        uint32_t lo = 0, hi = 0xFFFFFFFFu;
        bool blocks = true;
        Range()
        {
            if (const char *v = std::getenv("GOW_VU1C_RANGO"))
            {
                char *end = nullptr;
                lo = static_cast<uint32_t>(std::strtoul(v, &end, 16));
                hi = end && *end == '-' ? static_cast<uint32_t>(std::strtoul(end + 1, nullptr, 16)) : lo;
            }
            blocks = std::getenv("GOW_VU1C_SIN_BLOQUES") == nullptr;
        }
    } g_range;
    inline bool inRange(uint32_t pc) { return pc >= g_range.lo && pc <= g_range.hi; }
}

